ALTER TABLE public.campaign_players ADD COLUMN active boolean NOT NULL DEFAULT true, ADD COLUMN require_password_change boolean NOT NULL DEFAULT false;
CREATE TABLE public.campaign_admin_audit(id uuid PRIMARY KEY DEFAULT gen_random_uuid(),actor uuid NOT NULL,target_player uuid,action text NOT NULL,created_at timestamptz NOT NULL DEFAULT now(),details jsonb NOT NULL DEFAULT '{}'::jsonb);
GRANT SELECT ON public.campaign_admin_audit TO authenticated;
GRANT ALL ON public.campaign_admin_audit TO service_role;
ALTER TABLE public.campaign_admin_audit ENABLE ROW LEVEL SECURITY;
CREATE POLICY audit_admin_read ON public.campaign_admin_audit FOR SELECT TO authenticated USING(public.is_campaign_admin());
CREATE TABLE public.house_catalog(id text PRIMARY KEY,name text NOT NULL,region text NOT NULL,classification text NOT NULL DEFAULT 'noble',archive_data jsonb NOT NULL,source_folder_id text UNIQUE,public_reviewed boolean NOT NULL DEFAULT false,updated_at timestamptz NOT NULL DEFAULT now());
GRANT SELECT ON public.house_catalog TO anon,authenticated;
GRANT ALL ON public.house_catalog TO service_role;
ALTER TABLE public.house_catalog ENABLE ROW LEVEL SECURITY;
CREATE POLICY catalog_public_read ON public.house_catalog FOR SELECT TO anon,authenticated USING(public_reviewed);
CREATE OR REPLACE FUNCTION public.my_player_id() RETURNS uuid LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT id FROM public.campaign_players WHERE user_id=auth.uid() AND active AND NOT require_password_change LIMIT 1 $$;
CREATE OR REPLACE FUNCTION public.in_campaign_house(h text,edit_required boolean DEFAULT false) RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT EXISTS(SELECT 1 FROM public.house_memberships m JOIN public.campaign_players p ON p.id=m.player_id WHERE p.user_id=auth.uid() AND p.active AND NOT p.require_password_change AND m.house_id=h AND (NOT edit_required OR m.can_edit)) $$;
CREATE OR REPLACE FUNCTION public.campaign_access_active() RETURNS boolean LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT public.is_campaign_admin() OR public.my_player_id() IS NOT NULL $$;
CREATE OR REPLACE FUNCTION public.can_read_letter(l public.campaign_letters) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT public.is_campaign_admin() OR (public.campaign_access_active() AND l.deleted_at IS NULL AND (l.sender_user_id=auth.uid() OR (l.publication_state='delivered' AND coalesce(public.letter_recipient(l),false)))) $$;
CREATE OR REPLACE FUNCTION public.can_read_reply(r public.letter_replies) RETURNS boolean LANGUAGE sql STABLE SET search_path=public AS $$ SELECT public.is_campaign_admin() OR (public.campaign_access_active() AND (r.author_user_id=auth.uid() OR (r.publication_state='delivered' AND r.recipient_user_id=auth.uid() AND EXISTS(SELECT 1 FROM public.campaign_letters l WHERE l.id=r.letter_id AND public.can_read_letter(l))))) $$;
CREATE OR REPLACE FUNCTION public.public_player_houses() RETURNS TABLE(house_id text) LANGUAGE sql STABLE SECURITY DEFINER SET search_path=public AS $$ SELECT DISTINCT m.house_id FROM public.house_memberships m JOIN public.campaign_players p ON p.id=m.player_id WHERE p.active AND p.user_id IS NOT NULL $$;
REVOKE ALL ON FUNCTION public.public_player_houses() FROM PUBLIC;
GRANT EXECUTE ON FUNCTION public.public_player_houses() TO anon,authenticated;
ALTER POLICY receipts_read ON public.letter_receipts USING(public.is_campaign_admin() OR (public.campaign_access_active() AND user_id=auth.uid()));
ALTER POLICY campaign_images_read ON storage.objects USING (bucket_id='campaign-images' AND (public.is_campaign_admin() OR (public.campaign_access_active() AND ((storage.foldername(name))[1]=auth.uid()::text OR EXISTS(SELECT 1 FROM public.campaign_letters l WHERE l.publication_state='delivered' AND public.can_read_letter(l) AND position('[cormyr-image:'||objects.name||'|' in l.content)>0) OR EXISTS(SELECT 1 FROM public.letter_replies r WHERE r.publication_state='delivered' AND public.can_read_reply(r) AND position('[cormyr-image:'||objects.name||'|' in r.content)>0) OR EXISTS(SELECT 1 FROM public.campaign_records r WHERE public.can_read_record(r) AND position('[cormyr-image:'||objects.name||'|' in r.content)>0)))));